-- Fixture for the OpenCode reader of `stone usage` (issue #328).
-- Source: real sessions from OpenCode 2.2.6 on 2026-11-17, kept in the same tables with only the columns
-- that the parser reads. Message text is removed and the folder is changed to /work/project.
-- ses_e18fb2f5... and ses_e18faf89... : deepseek-v4.1-flash at 01:00 UTC on a Tuesday (peak window).
-- ses_offpeak0deepseek0copy: a copy of ses_e18faf89... with the time moved by 4 hours to 05:00 UTC
--   (off-peak). It has the same tokens. ses_e18de5fd...: glm-5.3-flash (no peak rates).
-- ses_e18de447...: beam-free (no rates). ses_child0of0glm0session: a copy of the glm session
--   with a parent, to test the subagent kind.
CREATE TABLE session_v2 (id TEXT PRIMARY KEY, parent_id TEXT, directory TEXT NOT NULL, time_created INTEGER NOT NULL);
CREATE TABLE session_message (id TEXT PRIMARY KEY, session_id TEXT NOT NULL, type TEXT NOT NULL, seq INTEGER NOT NULL, time_created INTEGER NOT NULL, data TEXT NOT NULL);
